def is_in_between(numbers: List[float], number_to_test: float) -> bool:
    """ Check if given number is between any two numbers in provided list.

    >>> is_in_between([1.0, 2.0, 3.0], 1.5)
    True
    >>> is_in_between([1.0, 2.0, 3.0], -1)
    False
    """
    index_min = 0
    index_max = len(numbers) - 1

    while numbers[index_max] >= number_to_test > numbers[index_min]:

        average_min = (numbers[index_min] + numbers[index_max]) / 2

        if average_min == number_to_test:
            return True
        elif average_min < number_to_test < numbers[index_min]:
            return False

    return any(map(lambda x1, x2: abs(x1 - x2) <= threshold, numbers[:-1], numbers[1:]))

